            ast::TypeDefKind::Enum(variants) => { if variants.len() == 0 { self.err("E0420", t.name.span, "an enum needs at least one variant"); } let mut seen: Vec<String> = Vec::new(); let mut vout: Vec<types::VariantSig> = Vec::new(); for i in 0..variants.len() invariant 0 <= i && i <= variants.len(), { if !types::add(&mut seen, variants[i].name.name.as_str()) { } let mut tys: Vec<ast::TypeKind> = Vec::new(); for j in 0..variants[i].payload.len() invariant 0 <= j && j <= variants[i].payload.len() && i < variants.len(), { let ty: ast::TypeKind = self.field_type(&variants[i].payload[j], mp); tys.push(ty); } vout.push(types::VariantSig { name: variants[i].name.name.clone(), tys: tys }); } types::AdtKind::Enum(vout) },
